import { readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { config } from '../config.js';
import type { WorkflowSeedDefinition } from '../seed.js';

/**
 * Load built-in workflow seed definitions from database/workflows/*.json.
 *
 * Workflow definitions are database-owned (see CLAUDE.md); these JSON files are the
 * seed source a fresh database bootstraps from. They are generated by
 * scripts/export-workflows.ts. This loader only reads data — the caller inserts each
 * definition with insert-if-missing (keyed on `code`, never overwriting an existing row).
 */
export function loadWorkflowSeedDefinitionsFromDisk(
  dir = path.join(config.rootDir, 'database', 'workflows'),
): WorkflowSeedDefinition[] {
  let files: string[];
  try {
    files = readdirSync(dir)
      .filter((file) => file.endsWith('.json'))
      .sort();
  } catch {
    // No seed directory present (e.g. a minimal deploy) — nothing to bootstrap.
    return [];
  }

  return files.map((file) => {
    const doc = JSON.parse(readFileSync(path.join(dir, file), 'utf8')) as Partial<WorkflowSeedDefinition>;
    if (!doc.code || !doc.name) {
      throw new Error(`Invalid workflow seed file ${file}: missing "code" or "name".`);
    }
    return {
      code: doc.code,
      name: doc.name,
      description: doc.description ?? '',
      status: 'active',
      version: typeof doc.version === 'number' ? doc.version : 1,
      tasks: doc.tasks ?? [],
      runtimeParamsSchema: doc.runtimeParamsSchema ?? {},
      runtimeParamsDefaults: doc.runtimeParamsDefaults ?? {},
    };
  });
}
